// ── 任意人數（2–10）動態桌型 ──
// 開蓋全下範圍只取決於「後面還有幾人（k）」與有效計分牌，跟桌子叫幾 max 無關（見 gtoopen.py 的
// multiway_open(E,S,k)）。座位的 k＝在座位序中「後面還有幾人」（gtopushfoldopen 由 index 算），
// 所以位置「名稱」純粹是顯示用，可自由命名而不影響範圍正確性。
// 命名採自然慣例：最早行動一律叫 UTG、按鈕一律 BTN，中間依標準名（MP/LJ/HJ/CO）補；人多才往前加 UTG+1/UTG+2。
let GTONONBLIND_BY_N={
	3:  ["BTN"],
	4:  ["UTG","BTN"],
	5:  ["UTG","CO","BTN"],
	6:  ["UTG","MP","CO","BTN"],
	7:  ["UTG","MP","HJ","CO","BTN"],
	8:  ["UTG","UTG1","MP","HJ","CO","BTN"],
	9:  ["UTG","UTG1","MP","LJ","HJ","CO","BTN"],
	10: ["UTG","UTG1","UTG2","MP","LJ","HJ","CO","BTN"]
}
// k（後面人數）→ 用來查 9MAX push/fold 資料的代表位置。k=1 是 SB(HU)，另外處理。
let GTOK2POS={ 9:"UTG", 8:"UTG", 7:"UTG1", 6:"MP", 5:"LJ", 4:"HJ", 3:"CO", 2:"BTN" }
function gtogentable(n){
	if(n<2){ n=2 }
	if(n>10){ n=10 }
	if(n==2){ return { positions:["SB","BB"], seats:["SB","BB"] } }
	let nb=GTONONBLIND_BY_N[n]
	return { positions:nb.concat(["SB"]), seats:nb.concat(["SB","BB"]) }
}

